def _split_year_suffix(raw: str):
    """
    Separa 'Nombre 2024' -> ('Nombre', '2024').
    Mantiene sufijos tipo '(v2)' pegados al nombre.
    """
    parts = raw.rsplit(' ', 1)
    if len(parts) == 2 and parts[1].isdigit() and len(parts[1]) == 4:
        return parts[0], parts[1]
    return raw, None

def _normalize_token(token: str) -> str:
    # Normaliza algunas variantes en las claves
    fixes = {
        "Saudi Arabian": "Saudi Arabia",
        "Abu Dhabi": "Abu Dhabi",
        "Mexican": "Mexico",
        "Great Britain": "Great Britain",
        "USA": "United States",
        "United States": "United States",
        "Azerbaiyan": "Azerbaijan",  # clave en ES sin tilde -> EN base
        "Emilia-Romagna": "Emilia-Romagna",
        "Vegas": "Las Vegas",
    }
    return fixes.get(token, token)

def _localize_gp_titles(gp_key: str):
    """
    A partir de la clave de GP_FUNCS devuelve {"en": "...", "es": "..."}.
    Conserva el año y sufijos tipo '(v2)'.
    """
    base, year = _split_year_suffix(gp_key)
    base = base.strip()
    # Si trae sufijos tipo "(v2)", se conservan
    # Ej: "Spain 2024 (v2)" => base="Spain 2024 (v2)" ya no separa el año;
    # tratamos "(v2)" dentro de la parte base:
    suffix = ""
    if "(" in base and base.endswith(")"):
        i = base.rfind("(")
        suffix = " " + base[i:]  # " (v2)"
        base = base[:i].strip()

    norm = _normalize_token(base)

    # Construye EN
    en_name = norm
    # Construye ES
    es_name = _GP_NAME_MAP_EN_ES.get(norm, base)  # si ya venía en ES, lo deja
    # Reconstruye con año y sufijo si los hay
    def pack(name):
        if year:
            return f"{name} {year}{suffix}"
        return f"{name}{suffix}"

    return {"en": pack(en_name), "es": pack(es_name)}



def list_available():
    return sorted(GP_FUNCS.keys())


def export_all_to_json():
    import json
    from pathlib import Path

    out_es = {}
    out_en = {}

    for gp_name, fn in GP_FUNCS.items():
        items = fn()
        out_es[gp_name] = _export(items, "es", source=f"{gp_name}")
        out_en[gp_name] = _export(items, "en", source=f"{gp_name}")

    Path("gp_questions_es.json").write_text(
        json.dumps(out_es, ensure_ascii=False, indent=2),
        encoding="utf-8"
    )
    Path("gp_questions_en.json").write_text(
        json.dumps(out_en, ensure_ascii=False, indent=2),
        encoding="utf-8"
    )


def main():
    parser = argparse.ArgumentParser(description="Exporta preguntas de Grandes Premios en ES/EN")
    parser.add_argument("--lang", choices=["es", "en"], default="es", help="Idioma de salida")

    # Modos ya existentes
    parser.add_argument("--gp", type=str, help='Nombre exacto del GP, p. ej.: "Qatar 2024"')
    parser.add_argument("--all", action="store_true", help="Exportar todas las secciones disponibles")

    # --- NUEVO: modos de partida ---
    parser.add_argument("--game-random", action="store_true",
                        help="Genera una partida (10 preguntas) eligiendo un GP aleatorio")
    parser.add_argument("--game-gp", type=str,
                        help='Genera una partida (10 preguntas) para el GP indicado (p.ej. "Qatar 2024")')
    parser.add_argument("--seed", type=int, default=None, help="Semilla RNG para reproducibilidad")

    args = parser.parse_args()
    rng = random.Random(args.seed)

    # --- NUEVO: prioridad a modos 'game' si se indican ---
    if args.game_random:
        game = build_game_random_gp(args.lang, rng)
        print(json.dumps(game, ensure_ascii=False, indent=2))
        return

    if args.game_gp:
        game = build_game_from_gp(args.game_gp, args.lang, rng)
        print(json.dumps(game, ensure_ascii=False, indent=2))
        return

    # --- Comportamiento anterior: exportación suelta ---
    if not args.all and not args.gp:
        parser.error('Debes indicar --gp "Nombre Año", --all, --game-random o --game-gp "Nombre Año"')

    data = []
    if args.all:
        for gp_name, fn in GP_FUNCS.items():
            items = fn()
            data.extend(_export(items, args.lang))
    else:
        fn = GP_FUNCS.get(args.gp)
        if not fn:
            print(json.dumps({
                "error": f'GP no encontrado: {args.gp}',
                "disponibles": list_available()
            }, ensure_ascii=False, indent=2))
            return
        data = _export(fn(), args.lang)

    print(json.dumps(data, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
